{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--muted:#6b6b6b;--accent:#7b5cff;--card:#fff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#222;background:var(--bg);-webkit-font-smoothing:antialiased}
    a{color:var(--accent);text-decoration:none}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;background:linear-gradient(180deg,rgba(123,92,255,0.06),transparent);position:sticky;top:0;backdrop-filter:saturate(1.1) blur(4px);z-index:40}
    nav{display:flex;gap:18px;align-items:center}
    .logo{font-weight:700;color:#111}
    .nav-link{font-size:0.95rem;color:var(--muted)}

    /* Page layout */
    main{max-width:1100px;margin:28px auto;padding:24px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start;margin-bottom:28px}
    .hero-card{background:var(--card);padding:26px;border-radius:12px;box-shadow:0 6px 20px rgba(25,25,25,0.06)}
    h1{margin:0 0 8px 0;font-size:1.85rem}
    p.lead{margin:0;color:var(--muted);line-height:1.5}

    /* Story / Masonry-like flow */
    .masonry{column-count:2;column-gap:20px}
    .brick{break-inside:avoid;margin-bottom:20px;background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(20,20,20,0.04)}
    .meta{font-size:0.9rem;color:var(--muted);margin-bottom:8px}

    /* Reveal animations */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}

    /* CTA */
    .cta-row{display:flex;gap:12px;align-items:center;margin-top:12px}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;border:0;cursor:pointer}
    .btn.secondary{background:transparent;color:var(--accent);border:1px solid rgba(123,92,255,0.12)}

    footer{max-width:1100px;margin:40px auto;color:var(--muted);font-size:0.9rem;padding:8px 24px}

    /* subtle diagonal pattern via inline SVG data-uri */
    body::before{content:'';position:fixed;inset:0;pointer-events:none;opacity:0.06;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160' viewBox='0 0 160 160'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%237b5cff'/><stop offset='1' stop-color='%23ffffff' stop-opacity='0.0'/></linearGradient></defs><rect width='160' height='160' fill='none'/><g stroke='rgba(123,92,255,0.12)' stroke-width='4'><path d='M0 40 L40 0 M40 160 L160 40 M0 80 L80 0 M80 160 L160 80' stroke-linecap='round' /></g></svg>");background-repeat:repeat;mix-blend-mode:screen}

    /* small screens */
    @media (max-width:820px){.hero{grid-template-columns:1fr;}.masonry{column-count:1}}
  </style>
</head>
<body>
  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav aria-label="Main navigation">
      <a class="nav-link" href="/index.html">Home</a>
      <a class="nav-link" href="/about.html">Why Work With Me</a>
      <a class="nav-link" href="/specialties.html">Focus Areas</a>
      <a class="nav-link" href="/approach.html">How I Work</a>
      <a class="nav-link" href="/book.html">Book</a>
      <a class="nav-link" href="/contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="hero-card reveal" data-reveal>
        <h1>About my practice</h1>
        <p class="lead">I provide intentional, confidential therapy for adults seeking steady, practical progress in their lives. Sessions are collaborative and grounded in clinical skill—focused on what matters to you right now.</p>
        <div class="cta-row" style="margin-top:14px">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn secondary" href="/contact.html">Ask a question</a>
        </div>
      </div>

      <aside class="hero-card reveal" data-reveal>
        <div class="meta">Location</div>
        <div>{{CITY}}, {{STATE}}</div>
        <hr style="margin:12px 0;border:none;border-top:1px solid #f0f0f0">
        <div class="meta">Contact</div>
        <div><a href="tel:{{PHONE}}">{{PHONE}}</a><br><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </aside>
    </section>

    <section class="masonry" aria-labelledby="story-heading">
      <article class="brick reveal" data-reveal>
        <h2 id="story-heading">A short story about why I do this work</h2>
        <p class="meta">A grounded invitation</p>
        <p>People come with a tangle of feelings and practical problems—work that matters, relationships that need attention, and fatigue that lowers the bandwidth for change. My role is to hold a steady, informed presence that helps you sort priorities, test small steps, and notice what's actually working.</p>
      </article>

      <article class="brick reveal" data-reveal>
        <h3>Clinical perspective</h3>
        <p class="meta">How I structure sessions</p>
        <p>I integrate evidence-informed approaches in a flexible way tailored to your concerns. We map understandable next steps together and make room for the real-life constraints you bring. Progress looks different for everyone — we'll track what matters to you, not a preset checklist.</p>
      </article>

      <article class="brick reveal" data-reveal>
        <h3>Boundaries & confidentiality</h3>
        <p class="meta">Important things to know</p>
        <p>Your conversations are held in confidence following professional ethics and legal requirements. I also discuss limits to confidentiality (for example, if there is risk of harm) and will work transparently about them. If you are in crisis or at imminent risk, please contact emergency services or your local crisis line immediately—therapy is not a substitute for emergency care.</p>
      </article>

      <article class="brick reveal" data-reveal>
        <h3>Who I work with</h3>
        <p class="meta">Typical focuses</p>
        <p>Adults navigating transitions, persistent anxiety or low mood, relationship shifts, life-stage decisions, and the ripple effects of stress. If you are unsure whether therapy is right for you, a brief consult or message can help clarify fit.</p>
      </article>

      <article class="brick reveal" data-reveal>
        <h3>Practice logistics</h3>
        <p class="meta">Session format</p>
        <p>I offer both in-person appointments in {{CITY}} and secure teletherapy. We discuss session frequency together; some clients prefer weekly support while others choose biweekly sessions. Payment, insurance, and cancellation policies are reviewed during intake.</p>
      </article>
    </section>

    <section class="brick reveal" data-reveal style="margin-top:22px">
      <h3>Courtship before commitment</h3>
      <p class="meta">A simple next step</p>
      <p>If you want to explore working together, the easiest way is to request an initial consult. That meeting is an opportunity to describe what brought you here, ask practical questions, and see if the fit feels right—no pressure, just clear information.</p>
      <div style="margin-top:12px"><a class="btn" href="/book.html">Request a consult</a></div>
    </section>
  </main>

  <footer>
    <div>Licensed clinician. Confidential practice. Not a crisis service. For emergencies, call local emergency services.</div>
  </footer>

  <script>
    (function(){
      // Scroll-triggered reveal with prefers-reduced-motion support
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (prefersReduce) {
        document.querySelectorAll('[data-reveal]').forEach(el=>el.classList.add('visible'));
        return;
      }
      const observer = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){ e.target.classList.add('visible'); observer.unobserve(e.target); }
        });
      },{threshold:0.12});
      document.querySelectorAll('[data-reveal]').forEach(el=>observer.observe(el));
    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Focus Areas — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffaf8;--muted:#655;--accent:#ff7a59;--card:#fff}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;color:#241919;background:var(--bg)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px;background:linear-gradient(180deg,rgba(255,122,89,0.06),transparent);position:sticky;top:0}
    nav{display:flex;gap:14px}
    .nav-link{font-size:0.95rem;color:var(--muted)}
    main{max-width:1100px;margin:20px auto;padding:20px}

    .grid{display:grid;grid-template-columns:1fr 360px;gap:22px}
    .focus-list{display:grid;gap:14px}
    .focus{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 8px 20px rgba(0,0,0,0.06)}
    .focus h3{margin:0 0 6px 0}
    .muted{color:var(--muted)}

    /* Planner widget */
    .planner{background:#fff;padding:14px;border-radius:12px;box-shadow:0 6px 18px rgba(0,0,0,0.06)}
    label{display:block;font-size:0.85rem;margin-top:12px;color:#333}
    select,input[type='text'],textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #eee;margin-top:6px;font-size:0.95rem}
    .row{display:flex;gap:8px}
    .small{flex:1}
    .btn{background:var(--accent);color:white;padding:10px 12px;border-radius:8px;border:0;cursor:pointer;margin-top:12px}
    .copy{background:#fff;border:1px solid rgba(0,0,0,0.08);color:var(--accent)}

    /* reveal */
    .reveal{opacity:0;transform:translateY(16px);transition:opacity 480ms ease,transform 480ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}

    @media (max-width:820px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav aria-label="Main navigation">
      <a class="nav-link" href="/index.html">Home</a>
      <a class="nav-link" href="/about.html">About</a>
      <a class="nav-link" href="/specialties.html">Focus Areas</a>
      <a class="nav-link" href="/approach.html">How I Work</a>
      <a class="nav-link" href="/book.html">Scheduling</a>
      <a class="nav-link" href="/contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="reveal" data-reveal>
      <h1>What I commonly help with</h1>
      <p class="muted">Each focus area includes practical strategies we can try together in session and between meetings.</p>
    </section>

    <section class="grid" style="margin-top:18px">
      <div>
        <div class="focus-list">
          <div class="focus reveal" data-reveal>
            <h3>Transition & life changes</h3>
            <p class="muted">Decisions about work, relationships, and new chapters.</p>
            <p>I help people navigate uncertainty, sort priorities, and make choices that align with values.</p>
          </div>

          <div class="focus reveal" data-reveal>
            <h3>Anxiety & task overwhelm</h3>
            <p class="muted">When worry steals energy for daily tasks.</p>
            <p>We develop manageable routines, experiment with cognitive tools, and practice small exposure to feared tasks.</p>
          </div>

          <div class="focus reveal" data-reveal>
            <h3>Low mood & motivation</h3>
            <p class="muted">Strategies to shift activity and meaning.</p>
            <p>Therapy helps reconnect to valued activities while building realistic expectations and pacing for change.</p>
          </div>

          <div class="focus reveal" data-reveal>
            <h3>Relationship patterns</h3>
            <p class="muted">Better communication and boundaries.</p>
            <p>We explore patterns, practice new responses, and focus on what's sustainable in your relationships.</p>
          </div>
        </div>
      </div>

      <aside class="planner reveal" data-reveal aria-labelledby="planner-heading">
        <h2 id="planner-heading">Session Planner</h2>
        <p class="muted">Build a simple plan to bring to your first session.</p>
        <label for="focus">Primary focus</label>
        <select id="focus">
          <option>Transition & life changes</option>
          <option>Anxiety & task overwhelm</option>
          <option>Low mood & motivation</option>
          <option>Relationship patterns</option>
          <option>Other</option>
        </select>

        <label for="frequency">Preferred rhythm</label>
        <select id="frequency">
          <option>Weekly</option>
          <option>Biweekly</option>
          <option>Monthly check-ins</option>
        </select>

        <label for="goal">A one-line practice goal</label>
        <input id="goal" type="text" placeholder="e.g., get through job transition with clearer priorities">

        <label for="steps">Two small next steps</label>
        <textarea id="steps" rows="3" placeholder="List two concrete steps you can try in the next two weeks"></textarea>

        <div class="row" style="margin-top:8px">
          <button id="build" class="btn">Create plan</button>
          <button id="copy" class="btn copy">Copy</button>
        </div>

        <pre id="output" style="white-space:pre-wrap;background:#fff8f6;padding:10px;border-radius:8px;margin-top:12px;border:1px dashed rgba(0,0,0,0.04)"></pre>
        <p class="muted" style="font-size:0.85rem;margin-top:10px">This is a plain-text summary you can paste into a message or bring to your first meeting.</p>
      </aside>
    </section>
  </main>

  <footer style="max-width:1100px;margin:30px auto;color:var(--muted);padding:8px 20px">Confidential practice. Not an emergency resource—if you are in immediate danger, call local emergency services.</footer>

  <script>
    (function(){
      // Reveal
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(prefersReduce){document.querySelectorAll('[data-reveal]').forEach(e=>e.classList.add('visible'));}
      else{
        const obs=new IntersectionObserver((es)=>{es.forEach(ent=>{if(ent.isIntersecting){ent.target.classList.add('visible');obs.unobserve(ent.target);}})},{threshold:0.12});
        document.querySelectorAll('[data-reveal]').forEach(el=>obs.observe(el));
      }

      // Session Planner logic
      const build = document.getElementById('build');
      const copy = document.getElementById('copy');
      const output = document.getElementById('output');
      function makeSummary(){
        const focus = document.getElementById('focus').value.trim();
        const freq = document.getElementById('frequency').value.trim();
        const goal = document.getElementById('goal').value.trim();
        const steps = document.getElementById('steps').value.trim();
        let lines = [];
        lines.push('Session Plan — Prepared for initial visit');
        lines.push('Primary focus: '+(focus||'Not specified'));
        lines.push('Preferred rhythm: '+(freq||'Not specified'));
        if(goal) lines.push('One-line goal: '+goal);
        if(steps) lines.push('Two small next steps:\n'+steps.replace(/\n/g,'\n'));
        lines.push('Notes: Brought to first session for collaborative review.');
        return lines.join('\n\n');
      }
      build.addEventListener('click',()=>{output.textContent = makeSummary();});
      copy.addEventListener('click',()=>{
        const text = output.textContent || makeSummary();
        navigator.clipboard && navigator.clipboard.writeText ? navigator.clipboard.writeText(text).then(()=>{
          copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy',1500);
        }).catch(()=>{alert('Unable to copy automatically — please select and copy manually.');}) : alert('Copy not supported.');
      });
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>How I Work — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6fbff;--accent:#0b7285;--muted:#445;--card:#fff}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;color:#102a2a;background:var(--bg)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px;background:linear-gradient(180deg,rgba(11,114,133,0.04),transparent);position:sticky;top:0}
    nav{display:flex;gap:14px}
    .nav-link{font-size:0.95rem;color:var(--muted)}
    main{max-width:1100px;margin:24px auto;padding:20px}

    .split{display:grid;grid-template-columns:360px 1fr;gap:22px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,0.06)}
    h1{margin:0 0 6px 0}
    .muted{color:var(--muted)}

    /* process steps */
    .steps{display:flex;flex-direction:column;gap:10px}
    .step{display:flex;gap:12px;align-items:flex-start}
    .bubble{width:44px;height:44px;border-radius:10px;background:linear-gradient(180deg,var(--accent),#3aa0b4);color:white;display:flex;align-items:center;justify-content:center;font-weight:700}

    /* Planner repeated here with slightly different style */
    .planner{background:linear-gradient(180deg,rgba(11,114,133,0.04),transparent);padding:12px;border-radius:10px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6f0f2;margin-top:6px}
    .btn{background:var(--accent);color:#fff;padding:10px 12px;border-radius:8px;border:0;cursor:pointer}
    .copy{background:#fff;border:1px solid rgba(0,0,0,0.06);color:var(--accent)}

    .reveal{opacity:0;transform:translateY(14px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}

    @media (max-width:900px){.split{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav aria-label="Main navigation">
      <a class="nav-link" href="/index.html">Home</a>
      <a class="nav-link" href="/about.html">About</a>
      <a class="nav-link" href="/specialties.html">Focus Areas</a>
      <a class="nav-link" href="/approach.html">How I Work</a>
      <a class="nav-link" href="/fees.html">Fees</a>
      <a class="nav-link" href="/contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="split">
      <aside class="card reveal" data-reveal>
        <h2>My approach</h2>
        <p class="muted">A gentle, structured partnership</p>
        <div style="margin-top:12px" class="steps">
          <div class="step">
            <div class="bubble">1</div>
            <div>
              <strong>Clarify first.</strong>
              <div class="muted">We begin with the immediate question: what matters most to you right now?</div>
            </div>
          </div>

          <div class="step">
            <div class="bubble">2</div>
            <div>
              <strong>Try small, clear experiments.</strong>
              <div class="muted">Rather than sweeping plans, we design doable steps and test them together.</div>
            </div>
          </div>

          <div class="step">
            <div class="bubble">3</div>
            <div>
              <strong>Adjust with data.</strong>
              <div class="muted">We check what worked and adapt—therapy is practical and iterative.</div>
            </div>
          </div>
        </div>
      </aside>

      <div>
        <article class="card reveal" data-reveal>
          <h1>What to expect in sessions</h1>
          <p class="muted">A short description that sets a practical tone</p>
          <p style="margin-top:8px">Sessions are collaborative. I listen for what you value and help translate that into small experiments and clearer choices. We use clinical methods suited to your situation—cognitive, behavioral, relational tools—chosen for clarity and real-world usefulness.</p>

          <h3 style="margin-top:12px">Confidentiality & limits</h3>
          <p class="muted">A necessary note</p>
          <p style="margin-top:8px">Conversations are protected by confidentiality in line with professional ethics and law. There are limits to confidentiality when safety concerns arise; we will discuss those explicitly. If you are experiencing a crisis or are in immediate danger, contact emergency services or local crisis resources right away.</p>
        </article>

        <article class="card reveal" data-reveal style="margin-top:16px">
          <h3>Scope and fit</h3>
          <p class="muted">Who benefits most</p>
          <p style="margin-top:8px">People seeking steady, practical change—those who want to convert insight into action and who are comfortable trying small shifts between sessions. If you have complex legal, medical, or urgent safety needs, we will make sure you have appropriate supports in place.</p>
        </article>

        <article class="card reveal" data-reveal style="margin-top:16px">
          <h3>Bring this plan with you</h3>
          <p class="muted">A quick planning tool below</p>
          <p style="margin-top:8px">Use the planner to create a concise agenda for your first meeting—what you want from therapy, a preferred schedule, and two next steps to try. It helps our first time together be efficient.</p>
        </article>

        <div class="card reveal" data-reveal style="margin-top:16px">
          <h3>Session Planner</h3>
          <div style="margin-top:8px" class="planner">
            <label for="topic">Top topic</label>
            <input id="topic" type="text" placeholder="What brings you in?">
            <label for="pace">Preferred pace</label>
            <select id="pace">
              <option>Weekly</option>
              <option>Biweekly</option>
              <option>Short-term/2-4 sessions</option>
            </select>
            <label for="intent">One immediate intention</label>
            <input id="intent" type="text" placeholder="e.g., reduce worry at bedtime">
            <label for="todo">One small behavior to try</label>
            <input id="todo" type="text" placeholder="e.g., 10 minutes of structured breathing">

            <div style="display:flex;gap:8px;margin-top:10px">
              <button id="makePlan" class="btn">Make summary</button>
              <button id="copyPlan" class="btn copy">Copy</button>
            </div>

            <pre id="planOut" style="margin-top:10px;background:#eaf8fb;padding:10px;border-radius:8px;white-space:pre-wrap;border:1px solid rgba(11,114,133,0.06)"></pre>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer style="max-width:1100px;margin:30px auto;color:var(--muted);padding:8px 20px">Licensed clinician. Confidential records maintained. If you are in crisis, call local emergency services.</footer>

  <script>
    (function(){
      // Reveal logic
      const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduce){document.querySelectorAll('[data-reveal]').forEach(e=>e.classList.add('visible'));}
      else{const observer=new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('visible');observer.unobserve(en.target);}})},{threshold:0.12});document.querySelectorAll('[data-reveal]').forEach(el=>observer.observe(el));}

      // Planner widget logic
      function buildText(){
        const t = document.getElementById('topic').value.trim();
        const p = document.getElementById('pace').value.trim();
        const i = document.getElementById('intent').value.trim();
        const td = document.getElementById('todo').value.trim();
        const lines = [];
        lines.push('Brief session agenda');
        if(t) lines.push('Topic: '+t);
        lines.push('Preferred pace: '+(p||'Not specified'));
        if(i) lines.push('Immediate intention: '+i);
        if(td) lines.push('Action to try: '+td);
        lines.push('Note: Bring this to the first session for collaborative planning.');
        return lines.join('\n\n');
      }
      const out = document.getElementById('planOut');
      document.getElementById('makePlan').addEventListener('click',()=>{out.textContent=buildText();});
      document.getElementById('copyPlan').addEventListener('click',()=>{
        const text = out.textContent || buildText();
